const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s);
const W=900,H=600,colors=['#64f4ed','#89a7ff','#be95f7','#f386ba','#f4cb6b'],types=['multi','wide','fast','slow'],symbols=['✣','↔','»','«'];
let best=0;try{best=Math.max(0,Number(localStorage.getItem('neon-breaker-best'))||0)}catch{}$('#best').textContent=best;
let level=1,score=0,lives=3,balls=[],bricks=[],drops=[],particles=[],paddle={x:450,w:116},mode='intro',wide=0,speedEffect=0,speedTime=0,last=0,keys={},audioOn=false,audioCtx,toastTime=0;
function beep(freq=500){if(!audioOn)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.value=freq;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.09);o.start();o.stop(audioCtx.currentTime+.1)}catch{}}
function hud(){$('#level').textContent=String(level).padStart(2,'0');$('#score').textContent=score;$('#lives').textContent='♥ '.repeat(lives).trim()||'—';$('#best').textContent=best;$('#status').textContent=mode==='playing'?'挑戰進行中':mode==='ready'?'點擊場地或空白鍵發球':mode==='paused'?'遊戲已暫停':'等待玩家加入';$('#pause').textContent=mode==='paused'?'▶':'Ⅱ'}
function save(){if(score>best){best=score;try{localStorage.setItem('neon-breaker-best',String(best))}catch{notify('此瀏覽器無法儲存紀錄')}}}
function stage(){bricks=[];drops=[];wide=0;speedTime=0;speedEffect=0;paddle.w=116;const rows=Math.min(9,4+Math.floor(level/2)),cols=10;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){if(level>1&&((level%3===0&&(c+r)%4===0)||(level%3===1&&Math.abs(c-4.5)<r*.5)||(level%3===2&&(c+r)%7===0)))continue;const hp=1+Math.floor((level-1)/3)+(level>1&&(c+r)%3===0?1:0);bricks.push({x:35+c*83+(r%2&&level>2?8:0),y:65+r*31,w:75,h:23,hp,max:hp,color:colors[r%5]})}resetBall();mode='ready';hud()}
function resetBall(){balls=[{x:paddle.x,y:H-55,vx:0,vy:0,trail:[]}];drops=[]}
function launch(){if(mode!=='ready')return;mode='playing';balls[0].vx=130;balls[0].vy=-baseSpeed();$('#overlay').style.display='none';hud();beep(700)}
function baseSpeed(){return Math.min(650,310+(level-1)*22)}
function show(title,message,button){$('#title').innerHTML=title;$('#message').textContent=message;$('#start').innerHTML=button+' <span>↗</span>';$('#overlay').style.display='flex'}
function start(){if(mode==='paused'){mode=beforePause;$('#overlay').style.display='none';hud();return}if(mode==='next'){level++;stage();$('#overlay').style.display='none';return}level=1;score=0;lives=3;paddle.x=W/2;stage();$('#overlay').style.display='none'}
let beforePause='playing';function pause(){if(mode==='paused'){start();return}if(mode!=='playing'&&mode!=='ready')return;beforePause=mode;mode='paused';show('休息一下，<br>下一球更精彩。','按 P 或下方按鈕繼續。','繼續遊戲');hud()}
function notify(t){$('#toast').textContent=t;$('#toast').style.opacity=1;toastTime=2}
function effect(type){beep(900);if(type==='multi'){const source=balls[0];if(source)for(const angle of [-.5,.5]){if(balls.length>=9)break;const speed=Math.hypot(source.vx,source.vy);balls.push({x:source.x,y:source.y,vx:source.vx*Math.cos(angle)-source.vy*Math.sin(angle),vy:source.vx*Math.sin(angle)+source.vy*Math.cos(angle),trail:[]})}}else if(type==='wide'){wide=15;paddle.w=180;paddle.x=Math.max(paddle.w/2,Math.min(W-paddle.w/2,paddle.x))}else{speedEffect=type==='fast'?1:-1;speedTime=12}notify({multi:'✣ 多重球！',wide:'↔ 板子加寬 · 15 秒',fast:'» 球速提升 · 12 秒',slow:'« 球速減慢 · 12 秒'}[type])}
function update(dt){if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('#toast').style.opacity=0}if(mode!=='playing'&&mode!=='ready')return;let dir=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0);paddle.x=Math.max(paddle.w/2,Math.min(W-paddle.w/2,paddle.x+dir*610*dt));if(mode==='ready'){balls[0].x=paddle.x;return}if(wide>0){wide-=dt;if(wide<=0)paddle.w=116}if(speedTime>0){speedTime-=dt;if(speedTime<=0)speedEffect=0}
const factor=speedEffect===1?1.35:speedEffect===-1?.72:1;
for(const b of balls){b.trail.unshift({x:b.x,y:b.y});if(b.trail.length>9)b.trail.pop();const steps=Math.max(1,Math.ceil(Math.hypot(b.vx,b.vy)*factor*dt/6));for(let step=0;step<steps;step++){const ox=b.x,oy=b.y;b.x+=b.vx*factor*dt/steps;b.y+=b.vy*factor*dt/steps;if(b.x<7){b.x=7;b.vx=Math.abs(b.vx)}if(b.x>W-7){b.x=W-7;b.vx=-Math.abs(b.vx)}if(b.y<7){b.y=7;b.vy=Math.abs(b.vy)}if(b.vy>0&&b.y+7>=H-40&&oy+7<=H-26&&b.x>=paddle.x-paddle.w/2-6&&b.x<=paddle.x+paddle.w/2+6){let a=Math.max(-1,Math.min(1,(b.x-paddle.x)/(paddle.w/2)))*1.05;const v=baseSpeed();b.vx=Math.sin(a)*v;b.vy=-Math.cos(a)*v;b.y=H-47;beep(360)}
for(const brick of bricks){if(brick.hp<=0)continue;const nx=Math.max(brick.x,Math.min(b.x,brick.x+brick.w)),ny=Math.max(brick.y,Math.min(b.y,brick.y+brick.h));if((b.x-nx)**2+(b.y-ny)**2>49)continue;if(oy+7<=brick.y||oy-7>=brick.y+brick.h){b.vy=-b.vy;b.y=oy}else{b.vx=-b.vx;b.x=ox}brick.hp--;beep(500+brick.hp*120);if(!brick.hp){for(let i=0;i<9;i++)particles.push({x:b.x,y:b.y,vx:(Math.random()-.5)*150,vy:(Math.random()-.5)*150,t:.5,color:brick.color});if(Math.random()<.24)drops.push({x:brick.x+brick.w/2,y:brick.y,type:types[Math.floor(Math.random()*4)]})}break}}}
balls=balls.filter(b=>b.y<H+20);if(!balls.length){lives--;if(!lives){mode='over';save();show('這次的旅程，<br>也很精彩。',`完成 ${score} 關 · 最高紀錄 ${best} 分`,'再挑戰一次');hud();return}wide=0;paddle.w=116;speedTime=0;speedEffect=0;resetBall();mode='ready';notify('還有 '+lives+' 次機會，準備發球');hud()}
for(const d of drops){d.y+=135*dt;if(d.y+12>=H-40&&d.y-12<=H-26&&Math.abs(d.x-paddle.x)<paddle.w/2+12){effect(d.type);d.y=H+40}}drops=drops.filter(d=>d.y<H+25);
if(bricks.every(b=>b.hp===0)){score++;save();mode='next';show('漂亮突破！',`通關分數 ${score} · 下一關有更堅硬的磚塊與全新排列`,'前往第 '+(level+1)+' 關');hud()}}
function round(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function draw(dt){ctx.clearRect(0,0,W,H);ctx.strokeStyle='#20314a40';ctx.lineWidth=1;for(let x=25;x<W;x+=30)for(let y=20;y<H;y+=30){ctx.fillStyle='#31435e60';ctx.fillRect(x,y,1,1)}for(const b of bricks){if(!b.hp)continue;ctx.fillStyle=b.color;ctx.globalAlpha=.22+.55*(b.hp/b.max);round(b.x,b.y,b.w,b.h,4);ctx.globalAlpha=1;ctx.strokeStyle=b.color;ctx.strokeRect(b.x+.5,b.y+.5,b.w-1,b.h-1);if(b.max>1){ctx.fillStyle='#fff';ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText(b.hp,b.x+b.w/2,b.y+16)}}ctx.shadowBlur=18;ctx.shadowColor='#64f4ed';ctx.fillStyle='#64f4ed';round(paddle.x-paddle.w/2,H-40,paddle.w,12,6);ctx.shadowBlur=0;for(const b of balls){b.trail.forEach((p,i)=>{ctx.globalAlpha=(1-i/9)*.2;ctx.fillStyle='#a5f9ff';ctx.beginPath();ctx.arc(p.x,p.y,6-i*.4,0,Math.PI*2);ctx.fill()});ctx.globalAlpha=1;ctx.shadowBlur=14;ctx.shadowColor='#b9ffff';ctx.fillStyle='#efffff';ctx.beginPath();ctx.arc(b.x,b.y,6,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}for(const d of drops){const i=types.indexOf(d.type);ctx.fillStyle=['#64f4ed','#8dec9a','#f386ba','#f4cb6b'][i];round(d.x-14,d.y-12,28,24,5);ctx.fillStyle='#081321';ctx.textAlign='center';ctx.font='bold 21px sans-serif';ctx.fillText(symbols[i],d.x,d.y+7)}particles=particles.filter(p=>p.t>0);for(const p of particles){if(mode==='playing'){p.t-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt}ctx.globalAlpha=Math.max(0,p.t*2);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3)}ctx.globalAlpha=1;if(wide>0||speedTime>0){ctx.font='12px sans-serif';ctx.textAlign='left';ctx.fillStyle='#8da8be';ctx.fillText((wide>0?'↔ '+Math.ceil(wide)+'s  ':'')+(speedTime>0?(speedEffect>0?'» ':'« ')+Math.ceil(speedTime)+'s':''),22,H-15)}}
function frame(t){const dt=Math.min((t-last)/1000||0,.035);last=t;update(dt);draw(dt);requestAnimationFrame(frame)}
function move(e){const r=canvas.getBoundingClientRect();paddle.x=Math.max(paddle.w/2,Math.min(W-paddle.w/2,(e.clientX-r.left)/r.width*W))}canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerdown',e=>{move(e);canvas.setPointerCapture(e.pointerId);launch()});document.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys[e.key]=true;if(e.code==='Space'&&!e.repeat){if(mode==='ready')launch();else if(mode==='intro'||mode==='over'||mode==='next')start()}if(e.code==='KeyP'&&!e.repeat)pause()});document.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>{keys={};if(mode==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='playing')pause()});$('#start').onclick=start;$('#pause').onclick=pause;$('#sound').onclick=()=>{audioOn=!audioOn;$('#sound').textContent='音效：'+(audioOn?'開':'關');beep()};stage();mode='intro';hud();requestAnimationFrame(frame);
